typedef unsigned int message_id_t;
typedef float rational_t;

#define WMESS_OVERFLOW 0x80000000
#define WMESS_MS_Press 0x00000002

class widget;

struct widget_vtable
{
  char before_message_handler[80];
  short message_handler_adjustment;
  short message_handler_reserved;
  void (*message_handler)(void *, message_id_t, message_id_t, rational_t, rational_t);
  char before_select[208];
  short select_adjustment;
  short select_reserved;
  void (*select)(void *, bool);
  short get_prev_item_adjustment;
  short get_prev_item_reserved;
  widget *(*get_prev_item)(void *);
  short get_next_item_adjustment;
  short get_next_item_reserved;
  widget *(*get_next_item)(void *);
};

struct widget_list_node
{
  widget_list_node *next;
  widget_list_node *prev;
  widget *value;
};

class widget_list_t
{
public:
  class iterator
  {
  public:
    widget_list_node *node;
    widget *operator*() const { return node->value; }
    iterator &operator++() { node = node->next; return *this; }
    bool operator!=(const iterator &other) const { return node != other.node; }
  };

  widget_list_node *sentinel;
  iterator begin() { iterator result = { sentinel->next }; return result; }
  iterator end() { iterator result = { sentinel }; return result; }
};

class widget
{
public:
  char padding0[16];
  widget_list_t children;
  char padding1[300];
  widget_vtable *vtable;

  void message_handler(message_id_t message, message_id_t overflow,
                       rational_t parm0, rational_t parm1)
  {
    widget_vtable *table = vtable;
    table->message_handler((char *)this + table->message_handler_adjustment,
                           message, overflow, parm0, parm1);
  }
};

class menu_item_widget : public widget
{
public:
  void select()
  {
    widget_vtable *table = vtable;
    table->select((char *)this + table->select_adjustment, false);
  }
};

class menu_widget : public widget
{
public:
  int num_items;
  menu_item_widget *sel_item;
  int default_sel_index;
  message_id_t to_prev, to_next;
  bool change_made;

  menu_item_widget *get_prev_item() const
  {
    widget_vtable *table = vtable;
    return (menu_item_widget *)table->get_prev_item(
      (char *)this + table->get_prev_item_adjustment);
  }

  menu_item_widget *get_next_item() const
  {
    widget_vtable *table = vtable;
    return (menu_item_widget *)table->get_next_item(
      (char *)this + table->get_next_item_adjustment);
  }

  void message_handler( message_id_t message, message_id_t overflow, rational_t parm0, rational_t parm1 );
};

void menu_widget::message_handler( message_id_t message, message_id_t overflow, rational_t parm0, rational_t parm1 )
{
  if ( !sel_item ) return;

  if ( message & to_prev )
  {
    get_prev_item()->select();
    message &= ~to_prev;  // kill this message before moving down
    change_made = true;
  }
  else if ( message & to_next )
  {
    get_next_item()->select();
    message &= ~to_next;  // kill this message before moving down
    change_made = true;
  }

  sel_item->message_handler( message, overflow, parm0, parm1 );


  if( message & WMESS_OVERFLOW )
  {
    if( overflow & WMESS_MS_Press )
    {
      widget_list_t::iterator child;
      for( child = children.begin(); child != children.end(); ++child )
      {
        // PEH: THIS CHECK DISALLOWS DOUBLE-DIPPING OF THE CHILDREN
        if( *child != sel_item )
        {
          (*child)->message_handler( WMESS_OVERFLOW, WMESS_MS_Press, parm0, parm1 );
        }
      }
    }
  }
}
